});

describe('verificarRealizacao (RN28)', () => {
  test.skip('permite médico dono realizar AGENDADA a partir do início', () => {
    expect(regras.verificarRealizacao(mkConsulta(), ator('MEDICO', true), AGORA)).toBe(null);
