  test.skip('recepção precisa de motivo para cancelar (RN26)', () => {
    expect(() => servicos.consultasService.cancelar(recepcaoAtor, consulta.id, {})).toThrow(/motivo/);
  });

  test.skip('remarcar para outro horário (RN27)', () => {
