    expect(res.body.inicio).toBe('2026-10-21 10:00');
  });
});

describe('POST /api/consultas/:id/realizar (RF09.4, RN28)', () => {
  test('médico dono registra atendimento realizado', async () => {
    const tokMed = await tokenDe(app, 'MEDICO');
