  test.skip('rejeita bloco com dia inválido', () => {
    expect(() =>
      servicos.agendaService.salvarGrade(recepcaoAtor, medicoCarlos.id, [
        { diaSemana: 7, horaInicio: '08:00', horaFim: '12:00' },
      ])
