  test.skip('rejeita horário fora do expediente 07-20', () => {
    expect(() =>
      servicos.agendaService.salvarGrade(recepcaoAtor, medicoCarlos.id, [
        { diaSemana: 1, horaInicio: '06:00', horaFim: '12:00' },
      ])
    ).toThrow(/entre 07:00 e 20:00/);
